{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "In human subjects, labetalol—which shares a primary carboxamide and secondary aliphatic amine with the query—had an absolute oral bioavailability of 28% (19-49%), supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "5-Hydroxytryptophan, an indole-containing amino acid, showed 49% absolute oral bioavailability in volunteers, supporting high F for an indole-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Cilomilast was almost completely bioavailable (96%) after oral administration in fasted humans, indicating that small molecules with polar groups can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Ebastine, a BCS-II drug with basic amine and aromatic groups, achieved about 40% oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Leucovorin showed 100% oral bioavailability at single doses up to 50 mg in humans, supporting high F for polar molecules with amide/amine functionality.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "AZD0837 had an absolute bioavailability of 22-52% in humans, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "PF-05241328 had 38% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Isradipine had a mean systemic availability of 16.5% in healthy volunteers, providing contradictory evidence that some small oral drugs fall below 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C22"],
      "claim": "One labetalol study reported oral bioavailability of 4-17% (mean 9%) at 200 mg, a contradictory outlier relative to other labetalol measurements.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of highly transferable human oral bioavailability data—labetalol ~28%, 5-HTP 49%, AZD0837 22-52%, PF-05241328 38%, and others ≥40%—supports F ≥20% for this tetrahydrocarbazole carboxamide. The main contradictory evidence (isradipine ~16-19%) comes from a structurally distinct dihydropyridine with extensive first-pass metabolism, and the closest carboxamide/amine analogue labetalol is mostly ≥20%. Therefore predict high, with moderate confidence due to borderline values and variability.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query itself is present in the supplied evidence.",
    "Labetalol bioavailability is highly variable (4-40%) depending on dose and conditions, so the closest analogue's F is not tightly defined.",
    "Isradipine demonstrates that high first-pass metabolism can reduce F below 20%, and the query's basic amine/carboxamide may undergo metabolism; human clearance data are not provided.",
    "Transfer scores are high but do not encode structural similarity; structural differences affect how strongly the low-F isradipine result applies."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

